/**
 * The Kosovo relief map's geometry: generated by scripts from Natural Earth
 * (border, 1:10m) and AWS Terrarium elevation (zoom 10), Web Mercator.
 * public/visit/kosovo-relief.webp is drawn in the same 1478×1625 space, so a
 * point's position on the image is project(lon, lat) / [W, H].
 */
export const MAP_W = 1478;
export const MAP_H = 1625;
const Z = 10;
const X0 = 145551;
const Y0 = 95950;
const WORLD = 256 * 2 ** Z;

export function project(lon: number, lat: number): [number, number] {
  const s = Math.sin((lat * Math.PI) / 180);
  return [((lon + 180) / 360) * WORLD - X0, (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * WORLD - Y0];
}

